import type { Question } from './questions';
import { CLOUD_SOURCE, NETWORK_SOURCE, localSource, type Track } from '../engine/types';

/** Original practice scenarios. Each row is prompt | answer | three distractors | rationale.
 * IDs are allocated per section, not by array position across the whole bank.
 * See docs/content-sources.md for provenance and the supplied-reference audit. */
function section(start: number, topic: Question['topic'], source: string, rows: string, track: Track = 'local'): Question[] {
  return rows.trim().split('\n').map((line,index) => {
    const fields=line.split('|').map(s=>s.trim());
    if (fields.length!==6) throw new Error(`Malformed authored question ${start+index}`);
    const [question,answer,...rest]=fields;
    return {id:start+index,question,options:[answer,...rest.slice(0,3)],correctAnswer:answer,correctAnswers:[answer],
      isMultiSelect:false,correctAnswersCount:1,topic,track,difficulty:'applied',objective:source,
      firewareVersion:track==='local'?'12.9.2 study baseline':undefined,explanation:rest[3],
      sources:[track==='local'?localSource(source):track==='cloud'?CLOUD_SOURCE:NETWORK_SOURCE]};
  });
}

